                           '    sh:path <http://data.ashrae.org/standard223#hasConnectionPoint> ;\n'
                           '    sh:sparql [ a sh:SPARQLConstraint ;\n'
                           '            rdfs:comment "Incompatible Medium. Case 2: A medium with '
                           'constituents and a pure medium."^^xsd:string ;\n'
                           '            sh:message "s223: {$this} has an incompatible medium {?m1} '
                           'with any constituent of {?m2}."^^xsd:string ;\n'
                           '            sh:prefixes '
                           '<http://data.ashrae.org/standard223/1.0/model/all> ;\n'
                           '            sh:select """\n'
                           'SELECT $this ?m2 ?m1\n'
                           'WHERE {\n'
                           '$this s223:cnx ?cp1, ?cp2 .\n'
                           '?cp1 a/rdfs:subClassOf* s223:ConnectionPoint .\n'
                           '?cp2 a/rdfs:subClassOf* s223:ConnectionPoint .\n'
                           'FILTER (?cp1 != ?cp2) .\n'
                           '?cp1 s223:hasMedium ?m1 .\n'
                           '?cp2 s223:hasMedium ?m2 .\n'
                           '?m2 s223:composedOf/s223:ofConstituent ?s2 .\n'
                           'FILTER NOT EXISTS {?m1 s223:composedOf ?c1} .\n'
                           'FILTER NOT EXISTS {\n'
                           '  ?m2 s223:composedOf/s223:ofConstituent ?s12 .\n'
                           '  {?s12 rdfs:subClassOf* ?m1} UNION {?m1 rdfs:subClassOf* ?s12} .\n'
                           '}\n'
